@Test
public void testHandleInputInputCmd() {
    CliContext ctx = new CliContext(System.in, System.out, System.err, ExitType.EXCEPTION);
    assertEquals(OperationResult.STOP_OPER, AbstractCli.handleInputCmd(ctx, AbstractCli.EXIT_COMMAND, connection));
    assertEquals(OperationResult.STOP_OPER, AbstractCli.handleInputCmd(ctx, AbstractCli.QUIT_COMMAND, connection));
    assertEquals(OperationResult.CONTINUE_OPER, AbstractCli.handleInputCmd(ctx, String.format("%s=", AbstractCli.SET_TIMESTAMP_DISPLAY), connection));
    assertEquals(OperationResult.CONTINUE_OPER, AbstractCli.handleInputCmd(ctx, String.format("%s=xxx", AbstractCli.SET_TIMESTAMP_DISPLAY), connection));
    assertEquals(OperationResult.CONTINUE_OPER, AbstractCli.handleInputCmd(ctx, String.format("%s=default", AbstractCli.SET_TIMESTAMP_DISPLAY), connection));
    assertEquals(OperationResult.CONTINUE_OPER, AbstractCli.handleInputCmd(ctx, AbstractCli.SHOW_TIMEZONE, connection));
    assertEquals(OperationResult.CONTINUE_OPER, AbstractCli.handleInputCmd(ctx, AbstractCli.SHOW_TIMESTAMP_DISPLAY, connection));
    assertEquals(OperationResult.CONTINUE_OPER, AbstractCli.handleInputCmd(ctx, AbstractCli.SHOW_FETCH_SIZE, connection));
    assertEquals(OperationResult.CONTINUE_OPER, AbstractCli.handleInputCmd(ctx, String.format("%s=%s", AbstractCli.SET_TIME_ZONE, "Asis/chongqing"), connection));
    assertEquals(OperationResult.CONTINUE_OPER, AbstractCli.handleInputCmd(ctx, String.format("%s=+08:00", AbstractCli.SET_TIME_ZONE), connection));
    assertEquals(OperationResult.CONTINUE_OPER, AbstractCli.handleInputCmd(ctx, String.format("%s=", AbstractCli.SET_FETCH_SIZE), connection));
    assertEquals(OperationResult.CONTINUE_OPER, AbstractCli.handleInputCmd(ctx, String.format("%s=111", AbstractCli.SET_FETCH_SIZE), connection));
}

