        Mockito.when(mockClientManager.borrowClient(remoteEndpoint)).thenReturn(mockClient);
        Mockito.doNothing().when(mockClient).onEndOfDataBlockEvent(Mockito.any(TEndOfDataBlockEvent.class));
        Mockito.doNothing().when(mockClient).onNewDataBlockEvent(Mockito.any(TNewDataBlockEvent.class));
    } catch (ClientManagerException | TException e) {
        e.printStackTrace();
        Assert.fail();
    }
    // Construct a mock SinkListener.
    SinkListener mockSinkListener = Mockito.mock(SinkListener.class);
    // Construct several mock TsBlock(s).
    List<TsBlock> mockTsBlocks = Utils.createMockTsBlocks(numOfMockTsBlock, mockTsBlockSize);
    // Construct SinkChannel.
    SinkChannel sinkChannel = new SinkChannel(remoteEndpoint, remoteFragmentInstanceId, remotePlanNodeId, localPlanNodeId, localFragmentInstanceId, mockLocalMemoryManager, Executors.newSingleThreadExecutor(), Utils.createMockTsBlockSerde(mockTsBlockSize), mockSinkListener, mockClientManager);
    sinkChannel.open();
    Assert.assertTrue(sinkChannel.isFull().isDone());
    Assert.assertFalse(sinkChannel.isFinished());
    Assert.assertFalse(sinkChannel.isAborted());
    Assert.assertEquals(DEFAULT_MAX_TSBLOCK_SIZE_IN_BYTES, sinkChannel.getBufferRetainedSizeInBytes());
    Assert.assertEquals(0, sinkChannel.getNumOfBufferedTsBlocks());
    // Send tsblocks.
    sinkChannel.send(mockTsBlocks.get(0));
    Assert.assertTrue(sinkChannel.isFull().isDone());
    Assert.assertFalse(sinkChannel.isFinished());
    Assert.assertFalse(sinkChannel.isAborted());
    Assert.assertEquals(mockTsBlockSize * numOfMockTsBlock + DEFAULT_MAX_TSBLOCK_SIZE_IN_BYTES, sinkChannel.getBufferRetainedSizeInBytes());
    Assert.assertEquals(numOfMockTsBlock, sinkChannel.getNumOfBufferedTsBlocks());
    //    Mockito.verify(mockMemoryPool, Mockito.timeout(10_0000).times(1))
    //        .reserve(
    //            queryId,
    //
    // FragmentInstanceId.createFragmentInstanceIdFromTFragmentInstanceId(localFragmentInstanceId),
    //            localPlanNodeId,
    //            mockTsBlockSize * numOfMockTsBlock,
    //            Long.MAX_VALUE);
    try {
        Mockito.verify(mockClient, Mockito.timeout(10_000).times(1)).onNewDataBlockEvent(Mockito.argThat(e -> remoteFragmentInstanceId.equals(e.getTargetFragmentInstanceId()) && remotePlanNodeId.equals(e.getTargetPlanNodeId()) && localFragmentInstanceId.equals(e.getSourceFragmentInstanceId()) && e.getStartSequenceId() == 0 && e.getBlockSizes().size() == numOfMockTsBlock));
    } catch (TException e) {
        e.printStackTrace();
        Assert.fail();
    }
    // Get tsblocks.
    for (int i = 0; i < numOfMockTsBlock; i++) {
        try {
            sinkChannel.getSerializedTsBlock(i);
        } catch (IOException e) {
            e.printStackTrace();
            Assert.fail();
        }
        Assert.assertTrue(sinkChannel.isFull().isDone());
    }
    Assert.assertFalse(sinkChannel.isFinished());
    // Set no-more-tsblocks.
    sinkChannel.setNoMoreTsBlocks();
    Assert.assertTrue(sinkChannel.isFull().isDone());
    Assert.assertFalse(sinkChannel.isFinished());
    Assert.assertFalse(sinkChannel.isAborted());
    Mockito.verify(mockSinkListener, Mockito.timeout(10_000).times(1)).onEndOfBlocks(sinkChannel);
    // Ack tsblocks.
    sinkChannel.acknowledgeTsBlock(0, numOfMockTsBlock);
    Assert.assertTrue(sinkChannel.isFull().isDone());
    Assert.assertTrue(sinkChannel.isFinished());
    Assert.assertFalse(sinkChannel.isAborted());
    Assert.assertEquals(mockTsBlockSize, sinkChannel.getBufferRetainedSizeInBytes());
    Mockito.verify(mockMemoryPool, Mockito.timeout(10_0000).times(1)).free(queryId, FragmentInstanceId.createFragmentInstanceIdFromTFragmentInstanceId(localFragmentInstanceId), localPlanNodeId, numOfMockTsBlock * mockTsBlockSize);
    Mockito.verify(mockSinkListener, Mockito.timeout(10_0000).times(1)).onFinish(sinkChannel);
    try {
        Mockito.verify(mockClient, Mockito.timeout(10_000).times(1)).onEndOfDataBlockEvent(Mockito.argThat(e -> remoteFragmentInstanceId.equals(e.getTargetFragmentInstanceId()) && remotePlanNodeId.equals(e.getTargetPlanNodeId()) && localFragmentInstanceId.equals(e.getSourceFragmentInstanceId()) && numOfMockTsBlock - 1 == e.getLastSequenceId()));
    } catch (TException e) {
        e.printStackTrace();
        Assert.fail();
    }
}

