// left.time>right.time: containsGreaterThan=true, ignoreEqual=false
// left.time<=right.time: containsGreaterThan=false, ignoreEqual=true
private void testExecute(boolean containsGreaterThan, boolean ignoreEqual, boolean deviceEqual, long[] time1Array, int[] column1Array, long[] time2Array, int[] column2Array, boolean[][] columnsIsNull) {
    FragmentInstanceContext fragmentInstanceContext = Mockito.mock(FragmentInstanceContext.class);
    Mockito.when(fragmentInstanceContext.getMemoryReservationContext()).thenReturn(new ThreadSafeMemoryReservationManager(new QueryId("1"), "test"));
    DriverContext driverContext = Mockito.mock(DriverContext.class);
    Mockito.when(driverContext.getFragmentInstanceContext()).thenReturn(fragmentInstanceContext);
    OperatorContext operatorContext = Mockito.mock(OperatorContext.class);
    Mockito.when(operatorContext.getMaxRunTime()).thenReturn(new Duration(1, TimeUnit.SECONDS));
    Mockito.when(operatorContext.getDriverContext()).thenReturn(driverContext);
    Operator leftChild = new Operator() {

        private final long[][] timeArray = containsGreaterThan ? (deviceEqual ? new long[][] { { 17L, 13L }, { 9L, 6L, 4L }, { 25L, 22L } } : new long[][] { { 25L, 22L }, { 17L, 13L }, { 9L, 6L, 4L } }) : new long[][] { { 4L, 6L, 9L }, { 13L, 17L }, { 22L, 25L } };

        private final Binary[][] deviceArray = containsGreaterThan ? (deviceEqual ? new Binary[][] { new Binary[] { d1, d1 }, new Binary[] { d1, d1, d1 }, new Binary[] { d2, d2 } } : new Binary[][] { new Binary[] { d2, d2 }, new Binary[] { d1, d1 }, new Binary[] { d1, d1, d1 } }) : new Binary[][] { new Binary[] { d1, d1, d1 }, new Binary[] { d1, d1 }, new Binary[] { d2, d2 } };

        private final int[][] valueArray = containsGreaterThan ? (deviceEqual ? new int[][] { { 17, 13 }, { 9, 6, 4 }, { 25, 22 } } : new int[][] { { 25, 22 }, { 17, 13 }, { 9, 6, 4 } }) : new int[][] { { 4, 6, 9 }, { 13, 17 }, { 22, 25 } };

        private final boolean[][][] valueIsNull = containsGreaterThan ? (deviceEqual ? new boolean[][][] { { { false, false }, { false, false, false }, { false, false } } } : new boolean[][][] { { { false, false }, { false, false }, { false, false, false } } }) : new boolean[][][] { { { false, false, false }, { false, false }, { false, false } } };

        private int index = 0;

        @Override
        public OperatorContext getOperatorContext() {
            return operatorContext;
        }

        @Override
        public TsBlock next() {
            TsBlockBuilder builder = new TsBlockBuilder(timeArray[index].length, Arrays.asList(TSDataType.TIMESTAMP, TSDataType.TEXT, TSDataType.INT32));
            for (int i = 0, size = timeArray[index].length; i < size; i++) {
                builder.getColumnBuilder(0).writeLong(timeArray[index][i]);
                builder.getColumnBuilder(1).writeBinary(deviceArray[index][i]);
                if (valueIsNull[0][index][i]) {
                    builder.getColumnBuilder(2).appendNull();
                } else {
                    builder.getColumnBuilder(2).writeInt(valueArray[index][i]);
                }
            }
            builder.declarePositions(timeArray[index].length);
            return builder.build(new RunLengthEncodedColumn(TIME_COLUMN_TEMPLATE, timeArray[index++].length));
        }

        @Override
        public boolean hasNext() {
            return index < 3;
        }

        @Override
        public void close() {
        }

        @Override
        public boolean isFinished() {
            return index >= 3;
        }

        @Override
        public long calculateMaxPeekMemory() {
            return 64 * 1024;
        }

        @Override
        public long calculateMaxReturnSize() {
            return 64 * 1024;
        }

        @Override
        public long calculateRetainedSizeAfterCallingNext() {
            return 0;
        }

        @Override
        public long ramBytesUsed() {
            return 0;
        }
    };
    Operator rightChild = new Operator() {

        private final long[][] timeArray = containsGreaterThan ? (deviceEqual ? new long[][] { { 10L, 5L, 4L }, { 3L, 2L, 1L }, { 27L, 26L }, { 16L, 13L } } : new long[][] { { 27L, 26L }, { 16L, 13L }, { 10L, 5L, 4L }, { 3L, 2L, 1L } }) : new long[][] { { 1L, 2L, 3L }, { 4L, 5L, 10L }, { 13L, 16L }, { 26L, 27L } };

        private final Binary[][] deviceArray = containsGreaterThan && !deviceEqual ? new Binary[][] { new Binary[] { d2, d2 }, new Binary[] { d2, d2 }, new Binary[] { d1, d1, d1 }, new Binary[] { d1, d1, d1 } } : new Binary[][] { new Binary[] { d1, d1, d1 }, new Binary[] { d1, d1, d1 }, new Binary[] { d2, d2 }, new Binary[] { d2, d2 } };

        private final int[][] valueArray = containsGreaterThan ? (deviceEqual ? new int[][] { { 100, 50, 40 }, { 30, 20, 10 }, { 270, 260 }, { 160, 130 } } : new int[][] { { 270, 260 }, { 160, 130 }, { 100, 50, 40 }, { 30, 20, 10 } }) : new int[][] { { 10, 20, 30 }, { 40, 50, 100 }, { 130, 160 }, { 260, 270 } };

        private final boolean[][][] valueIsNull = containsGreaterThan && !deviceEqual ? new boolean[][][] { { { false, false }, { false, false }, { false, false, false }, { false, false, false } } } : new boolean[][][] { { { false, false, false }, { false, false, false }, { false, false }, { false, false } } };

        private int index = 0;

        @Override
        public OperatorContext getOperatorContext() {
            return operatorContext;
        }

        @Override
        public TsBlock next() {
            TsBlockBuilder builder = new TsBlockBuilder(timeArray[index].length, Arrays.asList(TSDataType.TIMESTAMP, TSDataType.TEXT, TSDataType.INT32));
            for (int i = 0, size = timeArray[index].length; i < size; i++) {
                builder.getColumnBuilder(0).writeLong(timeArray[index][i]);
                builder.getColumnBuilder(1).writeBinary(deviceArray[index][i]);
                if (valueIsNull[0][index][i]) {
                    builder.getColumnBuilder(2).appendNull();
                } else {
                    builder.getColumnBuilder(2).writeInt(valueArray[index][i]);
                }
            }
            builder.declarePositions(timeArray[index].length);
            return builder.build(new RunLengthEncodedColumn(TIME_COLUMN_TEMPLATE, timeArray[index++].length));
        }

        @Override
        public boolean hasNext() {
            return index < 4;
        }

        @Override
        public void close() {
        }

        @Override
        public boolean isFinished() {
            return index >= 4;
        }

        @Override
        public long calculateMaxPeekMemory() {
            return 64 * 1024;
        }

        @Override
        public long calculateMaxReturnSize() {
            return 64 * 1024;
        }

        @Override
        public long calculateRetainedSizeAfterCallingNext() {
            return 0;
        }

        @Override
        public long ramBytesUsed() {
            return 0;
        }
    };
    AsofMergeSortInnerJoinOperator asofInnerJoinOperator = new AsofMergeSortInnerJoinOperator(operatorContext, leftChild, deviceEqual ? new int[] { 1, 0 } : new int[] { 0 }, new int[] { 0, 2 }, rightChild, deviceEqual ? new int[] { 1, 0 } : new int[] { 0 }, new int[] { 0, 2 }, JoinKeyComparatorFactory.getAsofComparators(deviceEqual ? Collections.singletonList(BinaryType.TEXT) : Collections.emptyList(), ignoreEqual, !containsGreaterThan), Arrays.asList(TSDataType.TIMESTAMP, TSDataType.INT32, TSDataType.TIMESTAMP, TSDataType.INT32));
    try {
        int count = 0;
        ListenableFuture<?> listenableFuture = asofInnerJoinOperator.isBlocked();
        listenableFuture.get();
        while (!asofInnerJoinOperator.isFinished() && asofInnerJoinOperator.hasNext()) {
            TsBlock tsBlock = asofInnerJoinOperator.next();
            if (tsBlock != null && !tsBlock.isEmpty()) {
                for (int i = 0, size = tsBlock.getPositionCount(); i < size; i++, count++) {
                    assertEquals(time1Array[count], tsBlock.getColumn(0).getLong(i));
                    assertEquals(columnsIsNull[0][count], tsBlock.getColumn(1).isNull(i));
                    if (!columnsIsNull[1][count]) {
                        assertEquals(column1Array[count], tsBlock.getColumn(1).getInt(i));
                    }
                    assertEquals(time2Array[count], tsBlock.getColumn(2).getLong(i));
                    assertEquals(columnsIsNull[1][count], tsBlock.getColumn(3).isNull(i));
                    if (!columnsIsNull[1][count]) {
                        assertEquals(column2Array[count], tsBlock.getColumn(3).getLong(i));
                    }
                }
            }
            listenableFuture = asofInnerJoinOperator.isBlocked();
            listenableFuture.get();
        }
        assertEquals(time1Array.length, count);
        assertEquals(time2Array.length, count);
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
