@Test
public void testQueryRelatedAuth() {
    String sql = String.format("SELECT * FROM %s.%s", DB1, TABLE1);
    ITableAuthChecker authChecker = Mockito.mock(ITableAuthChecker.class);
    // user `root` always succeed
    Mockito.doNothing().when(authChecker).checkTablePrivilege(eq(userRoot), any(), any(), any());
    // user `user1` don't hava testdb.table1's SELECT privilege
    String errorMsg = String.format("%s doesn't have %s privilege on TABLE %s.%s", user1, TableModelPrivilege.SELECT, DB1, TABLE1);
    Mockito.doThrow(new AccessDeniedException(errorMsg)).when(authChecker).checkTablePrivilege(eq(user1), eq(testdbTable1), eq(TableModelPrivilege.SELECT), any());
    // user `user2` has testdb.table1's SELECT privilege
    Mockito.doNothing().when(authChecker).checkTablePrivilege(eq(user2), eq(testdbTable1), eq(TableModelPrivilege.SELECT), any());
    String userName = userRoot;
    try {
        analyzeSQL(sql, userName, authChecker);
    } catch (Exception e) {
        fail(e.getMessage());
    }
    userName = user1;
    try {
        analyzeSQL(sql, userName, authChecker);
        fail("user1 should be denied");
    } catch (AccessDeniedException e) {
        assertEquals(AccessDeniedException.PREFIX + errorMsg, e.getMessage());
    } catch (Exception e) {
        fail("Unexpected exception : " + e.getMessage());
    }
    userName = user2;
    try {
        analyzeSQL(sql, userName, authChecker, DB1);
    } catch (Exception e) {
        fail(e.getMessage());
    }
}

