@Test
public void testValidate() {
    InsertRowStatement insertRowStatement = new InsertRowStatement();
    insertRowStatement.setDevicePath(new PartialPath(new String[] { "table1" }));
    // wrong id order
    // miss id3
    // the type of m2 is wrong
    insertRowStatement.setMeasurements(new String[] { "id2", "attr2", "m1", "m2", "id1" });
    insertRowStatement.setDataTypes(new TSDataType[] { TSDataType.STRING, TSDataType.STRING, TSDataType.DOUBLE, TSDataType.BLOB, TSDataType.STRING });
    insertRowStatement.setColumnCategories(new TsTableColumnCategory[] { TsTableColumnCategory.TAG, TsTableColumnCategory.ATTRIBUTE, TsTableColumnCategory.FIELD, TsTableColumnCategory.FIELD, TsTableColumnCategory.TAG });
    insertRowStatement.setValues(new String[] { "id2", "attr2", "m1", "m2", "id1" });
    InsertRow insertRow = new InsertRow(insertRowStatement, queryContext);
    insertRow.validateTableSchema(metadata, queryContext);
    // id3 should be added into the statement to generate right DeviceIds
    assertArrayEquals(new String[] { "id1", "id2", "id3", "m1", null, "attr2" }, insertRowStatement.getMeasurements());
    assertArrayEquals(new String[] { "id1", "id2", null, "m1", null, "attr2" }, insertRowStatement.getValues());
    assertArrayEquals(new TSDataType[] { TSDataType.STRING, TSDataType.STRING, TSDataType.STRING, TSDataType.DOUBLE, null, TSDataType.STRING }, insertRowStatement.getDataTypes());
    assertArrayEquals(new TsTableColumnCategory[] { TsTableColumnCategory.TAG, TsTableColumnCategory.TAG, TsTableColumnCategory.TAG, TsTableColumnCategory.FIELD, TsTableColumnCategory.FIELD, TsTableColumnCategory.ATTRIBUTE }, insertRowStatement.getColumnCategories());
}

