private AbstractCompactionTask prepareTask(long memCost, int fileNum, long timePartition) throws IOException, MetadataException, WriteProcessException {
    createFiles(1, 1, 1, 1, 1, 1, 1, 1, true, true);
    seqResources.get(seqResources.size() - 1).setStatusForTest(TsFileResourceStatus.COMPACTION_CANDIDATE);
    InnerSpaceCompactionTask task = new InnerSpaceCompactionTask(timePartition, tsFileManager, Collections.singletonList(seqResources.get(seqResources.size() - 1)), true, new ReadChunkCompactionPerformer(), 0);
    InnerSpaceCompactionTask mockTask = Mockito.spy(task);
    Mockito.doReturn(memCost).when(mockTask).getEstimatedMemoryCost();
    Mockito.doReturn(fileNum).when(mockTask).getProcessedFileNum();
    Mockito.doReturn(true).when(mockTask).isDiskSpaceCheckPassed();
    Mockito.doReturn(1).when(mockTask).getSumOfCompactionCount();
    Mockito.doReturn(true).when(mockTask).isCompactionAllowed();
    return mockTask;
}

