    QueryId queryId = new QueryId("stub_query");
    FragmentInstanceId instanceId = new FragmentInstanceId(new PlanFragmentId(queryId, 0), "stub-instance");
    ExecutorService instanceNotificationExecutor = IoTDBThreadPoolFactory.newFixedThreadPool(1, "test-instance-notification");
    FragmentInstanceStateMachine stateMachine = new FragmentInstanceStateMachine(instanceId, instanceNotificationExecutor);
    FragmentInstanceContext queryContext = createFragmentInstanceContext(instanceId, stateMachine, memoryReservationManager);
    queryContext.initializeNumOfDrivers(1);
    DataRegion dataRegion = Mockito.mock(DataRegion.class);
    queryContext.setDataRegion(dataRegion);
    list.getQueryContextSet().add(queryContext);
    Map<TVList, Integer> tvlistMap = new HashMap<>();
    tvlistMap.put(list, 100);
    queryContext.addTVListToSet(tvlistMap);
    // fragment instance execution
    IDriverScheduler scheduler = Mockito.mock(IDriverScheduler.class);
    List<IDriver> drivers = Collections.emptyList();
    ISink sinkHandle = Mockito.mock(ISink.class);
