    FragmentInstanceExecution execution = FragmentInstanceExecution.createFragmentInstanceExecution(scheduler, instanceId, queryContext, drivers, sinkHandle, stateMachine, -1, false, exchangeManager);
    queryContext.decrementNumOfUnClosedDriver();
    series.release();
}

