@Test
public void testProgressIndexRecorder() {
    HybridProgressIndex hybridProgressIndex = new HybridProgressIndex(new SimpleProgressIndex(3, 4));
    hybridProgressIndex = (HybridProgressIndex) hybridProgressIndex.updateToMinimumEqualOrIsAfterProgressIndex(new SimpleProgressIndex(6, 6));
    hybridProgressIndex = (HybridProgressIndex) hybridProgressIndex.updateToMinimumEqualOrIsAfterProgressIndex(new RecoverProgressIndex(1, new SimpleProgressIndex(1, 2)));
    hybridProgressIndex = (HybridProgressIndex) hybridProgressIndex.updateToMinimumEqualOrIsAfterProgressIndex(new RecoverProgressIndex(1, new SimpleProgressIndex(1, 3)));
    hybridProgressIndex = (HybridProgressIndex) hybridProgressIndex.updateToMinimumEqualOrIsAfterProgressIndex(new RecoverProgressIndex(2, new SimpleProgressIndex(4, 3)));
    hybridProgressIndex = (HybridProgressIndex) hybridProgressIndex.updateToMinimumEqualOrIsAfterProgressIndex(new RecoverProgressIndex(3, new SimpleProgressIndex(5, 5)));
    Assert.assertTrue(hybridProgressIndex.isAfter(new SimpleProgressIndex(6, 5)));
    Assert.assertTrue(hybridProgressIndex.isAfter(new RecoverProgressIndex(3, new SimpleProgressIndex(5, 4))));
    Assert.assertTrue(new MockProgressIndex(0).isAfter(tsFileResource.getMaxProgressIndex()));
    indexList.forEach(tsFileResource::updateProgressIndex);
    Assert.assertFalse(new MockProgressIndex(-1).isAfter(tsFileResource.getMaxProgressIndex()));
    Assert.assertFalse(new MockProgressIndex(0).isAfter(tsFileResource.getMaxProgressIndex()));
    Assert.assertFalse(new MockProgressIndex(1).isAfter(tsFileResource.getMaxProgressIndex()));
    Assert.assertFalse(new MockProgressIndex(INDEX_NUM - 1).isAfter(tsFileResource.getMaxProgressIndex()));
    Assert.assertTrue(new MockProgressIndex(INDEX_NUM).isAfter(tsFileResource.getMaxProgressIndex()));
    Assert.assertTrue(new MockProgressIndex(Integer.MAX_VALUE).isAfter(tsFileResource.getMaxProgressIndex()));
    Assert.assertFalse(new MockProgressIndex(1, INDEX_NUM - 1).isAfter(tsFileResource.getMaxProgressIndex()));
}

